import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../core/providers.dart';
import '../../../core/widgets/common.dart';
import 'bill_detail_screen.dart';

class BillsScreen extends ConsumerStatefulWidget{const BillsScreen({super.key});@override ConsumerState<BillsScreen> createState()=>_BillsScreenState();}
class _BillsScreenState extends ConsumerState<BillsScreen>{final search=TextEditingController();String filter='Open';@override void dispose(){search.dispose();super.dispose();}
@override Widget build(BuildContext context){final bills=ref.watch(hydratedBillsProvider);final query=search.text.toLowerCase();final rows=bills.where((b){final status=b['status']=='closed'?'Closed':'Open';return(filter=='All'||filter==status)&&'${b['bill_no']} ${b['name']} ${b['mobile']} ${b['place']}'.toLowerCase().contains(query);}).toList()..sort((a,b)=>'${b['created_at']??''}'.compareTo('${a['created_at']??''}'));return Scaffold(appBar:AppBar(title:const Text('Bills'),actions:[IconButton(onPressed:()=>ref.refresh(billsProvider.future),icon:const Icon(Icons.sync))]),body:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(18,4,18,8),child:TextField(controller:search,onChanged:(_)=>setState((){}),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Bill, customer, mobile'))),Padding(padding:const EdgeInsets.symmetric(horizontal:18),child:Row(children:['Open','Closed','All'].map((x)=>Padding(padding:const EdgeInsets.only(right:8),child:ChoiceChip(label:Text(x),selected:filter==x,onSelected:(_)=>setState(()=>filter=x)))).toList())),Expanded(child:rows.isEmpty?const EmptyState(title:'No matching bills',description:'Change the filter or create a new rental bill.'):ListView.separated(padding:const EdgeInsets.all(16),itemCount:rows.length,itemBuilder:(context,i){final b=rows[i];return _BillRow(bill:b,onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>BillDetailScreen(billNo:'${b['bill_no']}'))));},separatorBuilder:(_,__)=>const SizedBox(height:9)))]) );}}
class _BillRow extends StatelessWidget{const _BillRow({required this.bill,required this.onTap});final Map<String,dynamic> bill;final VoidCallback onTap;@override Widget build(BuildContext context)=>Card(child:ListTile(onTap:onTap,contentPadding:const EdgeInsets.symmetric(horizontal:16,vertical:6),leading:CircleAvatar(child:Text('${bill['name']??'S'}'.trim().isEmpty?'S':'${bill['name']}'.trim()[0].toUpperCase())),title:Text('${bill['name']??'Customer'}',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('Bill #${bill['bill_no']} · ${bill['place']??'—'}'),trailing:Column(mainAxisAlignment:MainAxisAlignment.center,crossAxisAlignment:CrossAxisAlignment.end,children:[Text(moneyLabel(bill['pending']??0),style:const TextStyle(fontWeight:FontWeight.w800)),Text('${bill['status']=='closed'?'CLOSED':'OPEN'}',style:const TextStyle(fontSize:9))])));}
